CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,title TEXT NOT NULL,semester TEXT NOT NULL,opens_at TEXT NOT NULL,closes_at TEXT NOT NULL,capacity INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS modules(id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL REFERENCES courses(id),name TEXT NOT NULL,kind TEXT NOT NULL,weight INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(course_id,name));
CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL REFERENCES courses(id),student_id INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL,title TEXT NOT NULL,ai_statement TEXT NOT NULL,due_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,submitted_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(course_id,student_id,title));
CREATE TABLE IF NOT EXISTS evidences(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id),version INTEGER NOT NULL,uri TEXT NOT NULL,checksum TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(submission_id,version));
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY AUTOINCREMENT,submission_id INTEGER NOT NULL REFERENCES submissions(id),reviewer_id INTEGER NOT NULL REFERENCES users(id),decision TEXT NOT NULL,comment TEXT NOT NULL,version INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,action TEXT NOT NULL,result TEXT NOT NULL,request_id TEXT NOT NULL,metadata TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_records(key TEXT PRIMARY KEY,operation TEXT NOT NULL,user_id INTEGER NOT NULL,result_id INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS outbox_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,run_after TEXT NOT NULL,last_error TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_submissions_course_status ON submissions(course_id,status); CREATE INDEX IF NOT EXISTS idx_jobs_status_run ON outbox_jobs(status,run_after);
